const item = $input.item.json;
const p = item.playerProfile;

return [{
  json: {
    ...item,
    rankingExcludeClub: item.clubPlayerData,
    position: p.position,
    criteria: p.weightedCriteria,
    constraints: p.constraints || [],
    limit: 5
  }
}];

const item = $input.item.json;
const ranking = item.playerRanking;

if (!ranking || !ranking.dataAvailable || !Array.isArray(ranking.ranking) || ranking.ranking.length === 0) {
  return [{
    json: {
      ...item,
      playerSearch: { simulated: false, dataAvailable: false, longlistSize: 0, shortlist: [] }
    }
  }];
}

const pool = ranking.ranking;
const statFields = Object.keys(pool[0].stats).filter((f) => f !== 'age');
const poolAverage = {};
statFields.forEach((field) => {
  poolAverage[field] = pool.reduce((sum, p) => sum + p.stats[field], 0) / pool.length;
});

const shortlist = pool.slice(0, 5).map((candidate) => {
  const strengths = [];
  const weaknesses = [];
  statFields.forEach((field) => {
    const avg = poolAverage[field];
    if (candidate.stats[field] > avg) strengths.push(`${field}: ${candidate.stats[field]} (Pool-Schnitt ${avg.toFixed(2)})`);
    else if (candidate.stats[field] < avg) weaknesses.push(`${field}: ${candidate.stats[field]} (Pool-Schnitt ${avg.toFixed(2)})`);
  });

  return {
    name: candidate.name,
    score: candidate.score,
    strengths: strengths.length > 0 ? strengths : [`Score ${candidate.score} im CSV-Player-Ranking.`],
    weaknesses: weaknesses.length > 0 ? weaknesses : ['Keine auffaelligen Schwaechen gegenueber dem betrachteten CSV-Pool.'],
    evidence: [`CSV-Analytics-Datenpunkt (Data Table football_scouting_raw): ${candidate.club}, ${candidate.position}, Alter ${candidate.age}, Rating ${candidate.stats.rating}, ${candidate.stats.goals} Tore, ${candidate.stats.assists} Vorlagen in ${candidate.stats.appearances} Einsaetzen.`]
  };
});

return [{
  json: {
    ...item,
    playerSearch: {
      simulated: false,
      dataAvailable: true,
      longlistSize: ranking.poolSize,
      shortlist
    }
  }
}];

const item = $input.item.json;
const shortlist = item.playerSearch.shortlist;

return shortlist.map((candidate) => ({
  json: {
    ...item,
    playerName: candidate.name,
    rankingCandidate: candidate
  }
}));

const items = $input.all();
if (items.length === 0) {
  return [{ json: { playerSearch: { shortlist: [], profileValidated: false }, valid: false, errorMessage: 'Profilabgleich lieferte keine Items.' } }];
}

const context = { ...items[0].json };
delete context.playerName;
delete context.rankingCandidate;
delete context.playerProfileLookup;

const evaluated = items.map((it) => {
  const candidate = it.json.rankingCandidate;
  const lookup = it.json.playerProfileLookup;
  const profile = (lookup && lookup.found && lookup.profile) ? lookup.profile : null;
  return { candidate, profile, profileValid: !!candidate && !!profile && !profile.dataError };
});

const validated = evaluated.filter((entry) => entry.profileValid);
const rejected = evaluated.filter((entry) => !entry.profileValid).map((entry) => entry.candidate && entry.candidate.name).filter(Boolean);

const shortlist = validated.map(({ candidate: c, profile: p }) => ({
  ...c,
  evidence: [...c.evidence, `CSV-Analytics-Spielerprofil (Data Table football_scouting_raw, get_player_profile): ${p.club}, ${p.position}, Alter ${p.age}, Rating ${p.rating}, ${p.goals} Tore, ${p.assists} Vorlagen in ${p.appearances} Einsaetzen.`],
  profile: p
}));

return [{ json: { ...context, playerSearch: { ...context.playerSearch, shortlist, profileValidated: true, candidatesWithoutValidProfile: rejected } } }];

const item = $input.item.json;
const s = item.playerSearch;
const errors = [];

const ignoredConstraints = (item.playerRanking && Array.isArray(item.playerRanking.ignoredConstraints)) ? item.playerRanking.ignoredConstraints : [];
if (ignoredConstraints.length > 0) errors.push('playerRanking.ignoredConstraints ist nicht leer: ' + JSON.stringify(ignoredConstraints) + '.');

const ignoredCriteria = (item.playerRanking && Array.isArray(item.playerRanking.ignoredCriteria)) ? item.playerRanking.ignoredCriteria : [];
if (ignoredCriteria.length > 0) errors.push('playerRanking.ignoredCriteria ist nicht leer: ' + JSON.stringify(ignoredCriteria) + '.');

if (item.playerRanking && item.playerRanking.positionFallbackApplied) errors.push('playerRanking.positionFallbackApplied ist gesetzt - die angeforderte Position konnte nicht belastbar gefiltert werden.');

if (!s || typeof s !== 'object') {
  errors.push('playerSearch fehlt oder ist kein Objekt.');
} else {
  if (typeof s.longlistSize !== 'number' || s.longlistSize <= 0) errors.push('playerSearch.longlistSize fehlt oder ist ungueltig.');
  if (!Array.isArray(s.shortlist) || s.shortlist.length === 0) errors.push('playerSearch.shortlist fehlt oder ist leer.');
  else if (s.shortlist.length > 5) errors.push('playerSearch.shortlist enthaelt mehr als fuenf Kandidaten.');
  else if (s.shortlist.some((c) => !c.name || typeof c.score !== 'number' || !Array.isArray(c.strengths) || !Array.isArray(c.weaknesses) || !Array.isArray(c.evidence) || !c.profile)) errors.push('playerSearch.shortlist enthaelt einen Kandidaten ohne vollstaendige Ranking- und Profildaten.');
  if (!s.profileValidated) errors.push('playerSearch.shortlist wurde nicht ueber get_player_profile fachlich validiert.');
}

const valid = errors.length === 0;
return [{ json: { ...item, valid, errorMessage: valid ? undefined : 'Die Spielersuche ist ungueltig und wird nicht fuer die weitere Recherche verwendet.\n\n' + errors.join('\n') } }];
